import json
import os
from datetime import datetime, timezone

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
MOVEMENTS_FILE = os.path.join(ROOT, 'data', 'movements.json')
CARDS_FILE = os.path.join(ROOT, 'data', 'movement-cards.json')

with open(MOVEMENTS_FILE, 'r', encoding='utf-8') as f:
    mv_data = json.load(f)

moves = mv_data['moves']
moves_by_id = {m['id']: m for m in moves}

CARDS = {}

def c(id, start_main, start_sub, fin_main, fin_sub, muscles, male_tip, female_tip, preg_status, preg_note, ref):
    if id not in moves_by_id:
        raise ValueError(f"Unknown id: {id}")
    CARDS[id] = {
        "start": { "main": start_main, "sub": start_sub },
        "finish": { "main": fin_main, "sub": fin_sub },
        "muscles": muscles,
        "male": male_tip,
        "female": female_tip,
        "preg": {
            "status": preg_status,
            "note": preg_note
        },
        "ref": ref
    }

